xml.Script:
        Colors[ 0] := 'FF0000'; // Red
        Colors[ 1] := 'FF6600'; // Orange
        Colors[ 2] := '0066FF'; // Blue
        Colors[ 3] := '00DD00'; // Green
        Colors[ 4] := 'FFEE00'; // Yellow
        Colors[ 5] := 'FFFFFF'; // White
        Colors[ 6] := '1FAF00';
        Colors[ 7] := '7F00FF';
        Colors[ 8] := 'FFAF00';
        Colors[ 9] := '0099FF';
        Colors[10] := '00FF7F';
        Colors[11] := 'AFFF00';
        Colors[12] := 'FF007F';
        Colors[13] := 'AF1F00';

        K := 0.6;

        W := K * 0.5;
        include 'Figures\Scripts\Cube_Coordinates.inc';

        s2 := sqrt(2);
        C0 := 1;
        C1 := s2 + 1;
        C2 := 2 * s2 + 1;

        procedure AddNormal(bx, by, bz);
        begin
            nx[i] := bx;
            ny[i] := by;
            nz[i] := bz;
            Inc(i);
        end;

        procedure AddNormals(ax, ay, az);
        begin
            AddNormal(-ax,-ay,-az);
            AddNormal(-ax,-ay, az);
            AddNormal(-ax, ay,-az);
            AddNormal(-ax, ay, az);
            AddNormal( ax,-ay,-az);
            AddNormal( ax,-ay, az);
            AddNormal( ax, ay,-az);
            AddNormal( ax, ay, az);
        end;

        i := 0;
        AddNormals(C0, C1, C2);
        AddNormals(C0, C2, C1);
        AddNormals(C1, C2, C0);
        AddNormals(C1, C0, C2);
        AddNormals(C2, C0, C1);
        AddNormals(C2, C1, C0);

        C20 := K * 0.71029864124335; // from _Macro_For_Cubic_Sphere
        D := C20 * (C1 + C2) / sqrt(c0^2 + c1^2 + c2^2);

        // All angles there: http://twistypuzzles.com/forum/viewtopic.php?f=1&p=358806
        A0 := Arccos((-2 + s2)/12);     // 92.7980362
        A1 := Arccos((-6 + s2)/ 8);     // 124.9753039
        A2 := Arccos((-1 - 6 * s2)/12); // 142.2266599; A1 + A2 + A3 = 2 * Pi;
